/**
 * Optimised WebP variants of the heaviest bundled photos, generated by
 * scripts/optimize-images.py into src/assets/optimized/<name>-<width>w.webp.
 * The full-size originals in src/assets are untouched (gallery, lightbox,
 * admin and structured data still use them).
 *
 * Admin-managed slots: when the Media Library assigns a photo to a slot, the
 * resolved URL is an R2 `/gallery-image/...` URL, NOT the bundled original.
 * `responsiveProps` only applies a srcSet while the slot still resolves to
 * the bundled original, so admin uploads/replacements behave exactly as before.
 */
import { images } from "@/lib/gallery";
import logoFullOriginal from "@/assets/logo-full.png";
import logoMarkOriginal from "@/assets/logo-mark.png";
import logoMarkTransparentOriginal from "@/assets/logo-mark-transparent.png";
import fireOriginal from "@/assets/fire-nyama-choma.jpg";
import chickenOriginal from "@/assets/chicken-on-grate-closeup-800w.webp";

const files = import.meta.glob<string>("/src/assets/optimized/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
});

export type ResponsiveImage = {
  /** The bundled full-size asset this set replaces. */
  original: string;
  /** Largest variant, used as the `src` fallback. */
  src: string;
  /** Smallest variant, e.g. for video posters. */
  smallest: string;
  srcSet: string;
};

function set(original: string, stem: string): ResponsiveImage {
  const variants = Object.entries(files)
    .map(([path, url]) => {
      const m = /\/([^/]+)-(\d+)w\.webp$/.exec(path);
      return m && m[1] === stem ? ([url, Number(m[2])] as const) : null;
    })
    .filter((v): v is readonly [string, number] => v !== null)
    .sort((a, b) => a[1] - b[1]);
  if (variants.length === 0) {
    // Variants not generated yet: fall back to the original so nothing breaks.
    return { original, src: original, smallest: original, srcSet: "" };
  }
  return {
    original,
    src: variants[variants.length - 1]![0],
    smallest: variants[0]![0],
    srcSet: variants.map(([url, w]) => `${url} ${w}w`).join(", "),
  };
}

export const responsive = {
  hero: set(images.entranceBananaLeaves, "entrance-banana-leaves"),
  pavilion: set(images.pavilionWide, "pavilion-wide"),
  craft: set(images.craft, "craft-detail"),
  drums: set(images.drums, "culture-drums"),
  zebra: set(images.gardenZebraSignpost, "garden-zebra-signpost"),
  garden: set(images.garden, "garden-umbrella-dining"),
  feast: set(images.feastPlatterMixed, "feast-platter-mixed"),
  sadzaGreens: set(images.sadzaGreensPlatter, "sadza-greens-platter"),
  food: set(images.food, "grilled-ribs-on-grill"),
  fire: set(fireOriginal, "fire-nyama-choma"),
  pork: set(images.porkSizzler, "pork-sizzler"),
  drink: set(images.traditionalDrinkPouring, "traditional-drink-pouring"),
  chicken: set(chickenOriginal, "chicken-on-grate-closeup-1600w"),
  logoFull: set(logoFullOriginal, "logo-full"),
  logoMark: set(logoMarkOriginal, "logo-mark"),
  logoMarkTransparent: set(logoMarkTransparentOriginal, "logo-mark-transparent"),
} satisfies Record<string, ResponsiveImage>;

/**
 * `src` / `srcSet` for an image slot. Uses the optimised variants only while
 * the slot still resolves to the bundled original; an admin-assigned (R2)
 * photo is returned untouched.
 */
export function responsiveProps(
  resolved: string,
  r: ResponsiveImage,
): { src: string; srcSet?: string } {
  return resolved === r.original && r.srcSet ? { src: r.src, srcSet: r.srcSet } : { src: resolved };
}
